-- LOCAL MOCK ONLY. Exact parent DDL from supplied D1 export; no production records.
CREATE TABLE auras ( id TEXT PRIMARY KEY, name TEXT NOT NULL, llm_id TEXT, facet TEXT, personality TEXT, role TEXT, blocklist TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) , tool_llm_id TEXT, org_id TEXT NOT NULL DEFAULT 'org', department_id TEXT, memory_count INTEGER NOT NULL DEFAULT 0, graph_node_count INTEGER NOT NULL DEFAULT 0, graph_edge_count INTEGER NOT NULL DEFAULT 0, relationship_count INTEGER NOT NULL DEFAULT 0, counts_updated_at TEXT, shared_memory_count INTEGER NOT NULL DEFAULT 0, non_personal_node_count INTEGER NOT NULL DEFAULT 0, non_personal_edge_count INTEGER NOT NULL DEFAULT 0, restricted_memory_count INTEGER NOT NULL DEFAULT 0, platform_managed INTEGER NOT NULL DEFAULT 0, lane TEXT NOT NULL DEFAULT 'aura-layer' CHECK (lane IN ('aura-layer', 'external')));
CREATE TABLE studio_members ( org_id TEXT NOT NULL, member_id TEXT NOT NULL, role TEXT NOT NULL, departments TEXT NOT NULL DEFAULT '[]', PRIMARY KEY (org_id, member_id) ) WITHOUT ROWID;
